#include <WiFi.h>
#include <DNSServer.h>
#include <WebServer.h>
#include <Preferences.h>
#include "esp_wifi.h"

// Cấu hình mạng quản lý ban đầu
const char* default_ssid = "esp32";
const char* default_pass = "dzs1tg009";

const byte DNS_PORT = 53;
DNSServer dnsServer;
WebServer server(80);
Preferences preferences;

String target_ssid;
bool is_attack_mode = false;
uint8_t base_mac[6];

// Giao diện Web cấu hình xịn, mượt mà
const char HTML_PAGE[] PROGMEM = R"=====(
<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width, initial-scale=1.0'><title>ESP32 High-Speed Config</title>
<style>body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;text-align:center;margin:0;padding:50px 10px;background:#1a1a2e;color:#fff;}
.card{display:inline-block;text-align:left;padding:30px;background:#162447;border-radius:12px;box-shadow:0 8px 20px rgba(0,0,0,0.5);width:100%;max-width:400px;}
h2{margin-top:0;color:#e43f5a;}input[type='text']{width:100%;padding:12px;margin:15px 0;border:none;border-radius:6px;background:#1f4068;color:#fff;font-size:16px;box-sizing:border-box;}
input[type='submit']{background:#e43f5a;color:white;padding:12px;border:none;border-radius:6px;cursor:pointer;width:100%;font-size:16px;font-weight:bold;transition:0.3s;}
input[type='submit']:hover{background:#ff4b6e;}</style></head>
<body><div class='card'><h2>Hệ Thống Spam 30 Mạng</h2>
<form action='/save' method='POST'><label>Nhập tên chuỗi 30 mạng muốn phát:</label>
<input type='text' id='ssid' name='ssid' placeholder='Ví dụ: Free Wi-Fi' required>
<input type='submit' value='Kích Hoạt Max Công Suất'></form></div></body></html>
)=====";

// Cấu trúc gói tin Beacon thô (802.11 Frame)
uint8_t beacon_packet[128] = {
    0x80, 0x00, // Frame Control (Beacon)
    0x00, 0x00, // Duration
    0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, // Destination (Broadcast)
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // Source MAC (Sẽ ghi đè tự động)
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // BSSID (Sẽ ghi đè tự động)
    0x00, 0x00, // Sequence Control
    // WIRELESS MANAGEMENT PARAMETERS
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // Timestamp
    0x64, 0x00, // Beacon Interval (100 TU)
    0x11, 0x04, // Capability Info (Mạng Open, không mật khẩu)
    0x00        // SSID Element ID (Độ dài và tên sẽ chèn vào sau)
};

void handleRoot() { server.send(200, "text/html", HTML_PAGE); }

void handleSave() {
  if (server.hasArg("ssid")) {
    target_ssid = server.arg("ssid");
    preferences.begin("spam-sys", false);
    preferences.putString("ssid", target_ssid);
    preferences.putBool("mode", true); // Chuyển sang chế độ phát 30 mạng ảo
    preferences.end();
    server.send(200, "text/html", "<h3>Da cấu hình! ESP32 dang vao che do phat 30 mang...</h3>");
    delay(1500);
    ESP.restart();
  }
}

void setup() {
  Serial.begin(115200);
  preferences.begin("spam-sys", true);
  is_attack_mode = preferences.getBool("mode", false);
  target_ssid = preferences.getString("ssid", "");
  preferences.end();

  if (!is_attack_mode) {
    // ---- CHẾ ĐỘ CẤU HÌNH BAN ĐẦU ----
    WiFi.mode(WIFI_AP);
    WiFi.softAP(default_ssid, default_pass);
    dnsServer.start(DNS_PORT, "*", WiFi.softAPIP());
    server.on("/", handleRoot);
    server.on("/save", handleSave);
    server.onNotFound(handleRoot);
    server.begin();
    Serial.println("Dang cho cau hinh tai mang 'esp32'...");
  } else {
    // ---- CHẾ ĐỘ SPAM 30 MẠNG MAX CÔNG SUẤT ----
    WiFi.mode(WIFI_AP);
    esp_wifi_set_promiscuous(true);
    esp_wifi_get_mac(WIFI_IF_AP, base_mac); 
    Serial.println("Kích hoạt chế độ phát 30 mạng thô tốc độ cao!");
  }
}

void loop() {
  if (!is_attack_mode) {
    dnsServer.processNextRequest();
    server.handleClient();
    delay(1);
  } else {
    // Ép xung tốc độ phát bằng vòng lặp Non-blocking cấp thấp
    uint8_t ssid_len = target_ssid.length();
    
    for (int i = 0; i < 30; i++) {
      // 1. Tạo 30 địa chỉ MAC ảo khác nhau từ MAC gốc để điện thoại nhận diện thành 30 thiết bị riêng biệt
      uint8_t fake_mac[6];
      memcpy(fake_mac, base_mac, 6);
      fake_mac[5] = base_mac[5] + i; // Thay đổi byte cuối cùng

      memcpy(&beacon_packet[10], fake_mac, 6); // Source MAC
      memcpy(&beacon_packet[16], fake_mac, 6); // BSSID

      // 2. Định dạng chuỗi tên mạng (SSID) cho gói tin thô
      beacon_packet[37] = ssid_len; // Ghi độ dài tên mạng
      memcpy(&beacon_packet[38], target_ssid.c_str(), ssid_len); // Ghi dữ liệu chuỗi tên

      // 3. Thêm các tham số kết thúc gói tin hỗ trợ chuẩn tốc độ cao
      int pos = 38 + ssid_len;
      beacon_packet[pos++] = 0x01; // Supported Rates Element ID
      beacon_packet[pos++] = 0x08; // Length
      uint8_t rates[] = {0x82, 0x84, 0x8b, 0x96, 0x24, 0x30, 0x48, 0x6c};
      memcpy(&beacon_packet[pos], rates, 8);
      pos += 8;

      beacon_packet[pos++] = 0x03; // DS Parameter Set (Kênh phát)
      beacon_packet[pos++] = 0x01; // Length
      beacon_packet[pos++] = 1;    // Ép phát trên Kênh tần số 1 (Tối ưu độ nhạy anten)

      // 4. Bắn gói tin trực tiếp ra không khí không qua bộ đệm hoãn (Zero-delay TX)
      esp_wifi_80211_tx(WIFI_IF_AP, beacon_packet, pos, true);
      
      // Delay cực ngắn 1ms giữa các mạng để chip không bị quá nhiệt và đạt mật độ sóng dày đặc nhất
      delayMicroseconds(1000); 
    }
  }
}
